import{_ as e,o as r,c as t,a2 as d}from"./chunks/framework.DfDAiEgj.js";const u=JSON.parse('{"title":"百度","description":"","frontmatter":{},"headers":[],"relativePath":"ai-company/baidu.md","filePath":"ai-company/baidu.md","lastUpdated":null}'),p={name:"ai-company/baidu.md"};function o(l,a,n,i,h,s){return r(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="百度" tabindex="-1">百度 <a class="header-anchor" href="#百度" aria-label="Permalink to &quot;百度&quot;">​</a></h1><h2 id="人物" tabindex="-1">人物 <a class="header-anchor" href="#人物" aria-label="Permalink to &quot;人物&quot;">​</a></h2><p>景鲲：现任百度集团副总裁、百度智能生活事业群组（SLG）总经理，百度人工智能产品委员会主席。全面负责小度系列硬件、小度助手和小度对话式人工智能操作系统（DuerOS）的产品、研发、运营、商务等工作。 曾历任百度搜索公司产品委员会主席、大搜索总产品架构师。加入百度之前担任微软首席研发总监，负责微软必应搜索亚洲市场的研发工作，也是微软小冰的创造者。<a href="https://baike.baidu.com/item/%E6%99%AF%E9%B2%B2/20432174" target="_blank" rel="noreferrer">1</a></p><h2 id="小度" tabindex="-1">小度 <a class="header-anchor" href="#小度" aria-label="Permalink to &quot;小度&quot;">​</a></h2><p>2018年，百度的小度智能音箱，以及华为AI音箱相继跟上，这些头部大厂率先抢占了市场和人心，而后第二梯队的思必驰、出门问问等产品又进一步参与了对话市场的瓜分。</p><p>2020年9月30日，百度将旗下智能生活事业群组业务小度科技拆分，完成独立融资。小度也被独立拆分<a href="https://wqw547243068.github.io/2020/04/29/dialogue-system/#%E5%AF%B9%E8%AF%9D%E7%AE%A1%E7%90%86" target="_blank" rel="noreferrer">3</a></p><h2 id="产品吐槽" tabindex="-1">产品吐槽 <a class="header-anchor" href="#产品吐槽" aria-label="Permalink to &quot;产品吐槽&quot;">​</a></h2><p>百度百科：半屏的时候目录没了。。<a href="https://baike.baidu.com/item/%E5%B0%8F%E5%86%B0/19880611?fromtitle=%E5%BE%AE%E8%BD%AF%E5%B0%8F%E5%86%B0&amp;fromid=14076870#reference-%5B36%5D-20599544-wrap" target="_blank" rel="noreferrer">2</a></p><h2 id="paddlepaddle" tabindex="-1">PaddlePaddle <a class="header-anchor" href="#paddlepaddle" aria-label="Permalink to &quot;PaddlePaddle&quot;">​</a></h2><p>自主研发的深度学习框架将赋予平台运营商更自由的发挥空间，减少对外部生态的依赖。但框架开发的门槛高，周期长，成本大，以百度为例，百度在2013年成立深度学习研究院，期间大量相关科学家与工程师参与研发，耗时三年才发布深度学习框架PaddlePaddle。<a href="https://pdf.dfcfw.com/pdf/H3_AP202101141450490555_1.pdf?1610622618000.pdf" target="_blank" rel="noreferrer">4</a></p><p>文档（没能代码及时反馈）：<a href="https://www.paddlepaddle.org.cn/documentation/docs/" target="_blank" rel="noreferrer">https://www.paddlepaddle.org.cn/documentation/docs/</a></p><p><a href="https://www.paddlepaddle.org.cn/ppde" target="_blank" rel="noreferrer">https://www.paddlepaddle.org.cn/ppde</a></p><h2 id="硬件" tabindex="-1">硬件 <a class="header-anchor" href="#硬件" aria-label="Permalink to &quot;硬件&quot;">​</a></h2><p>AI耳机：<a href="https://dumall.baidu.com/product/219462907494434?skuNo=S20202200910011" target="_blank" rel="noreferrer">https://dumall.baidu.com/product/219462907494434?skuNo=S20202200910011</a></p><h2 id="开源商业模式" tabindex="-1">开源商业模式 <a class="header-anchor" href="#开源商业模式" aria-label="Permalink to &quot;开源商业模式&quot;">​</a></h2><p>国外典型开源商业模式是，社区-产品-利润（典型的包括Spark，MySQL，Hadoop等等都是如此），这个模式已经被国外成功验证。</p><p>也就是说，在社区内提供开源、免费的产品，为开发者提供新的模块，商业版则是会提供Bug修复、性能优化 、增值功能 、技术支持等能力。</p><p>深度学习框架/平台的开源商业模式和其他领域的开源经典模式略有不同，并非所有的开源厂商都会免费提供产品，开源不等于免费，企业级用户在获得可修改的算法的同时依然有义务支付授权费用。</p><p>开源框架/平台能够节省设计和开发的时间，但选择任何一个开源平台都需要客户对这个平台充分熟悉。任何一个开发平台都不可能提供完全自由的设计空间，应用的实现受制于开源框架/平台和特性基础。</p><p>百度飞桨的社区建设，起步早，规模已经很大，可以说“社区”这道护城河已经又宽又深。旷视、华为等的产品，则需要从无到有去走社区-产品-利润的路。</p><p>虽然说，百度和华为都在芯片、云、深度学习平台三者之间构建起了智能硬件到算法软件再到算力供给的智能制造解决方案大闭环，具备端到端软硬一体的能力。</p><p>但真正值得注意的是，还是百度和华为这样体量较大的公司，它们的未来空间的想象力，主要在于两块。</p><p>一块是复杂场景的考验，想要真正部署落地，往往需要全面能力，其中包括Serving、服务器端集成、移动/边缘/AI芯片等多种芯片上的集成，Web端集成等，这是一个系统工程。</p><p>另一块是系统工程的整合，供应链体系需要ARM这类提供CPU和GPU的国外厂商配合支撑。系统工程对大厂而言会显得相对游刃有余，对创业公司来说，需要多多观察。</p><p>帮百度AI干脏活累活的公司，都死了：<a href="https://xueqiu.com/3544180334/122723921" target="_blank" rel="noreferrer">https://xueqiu.com/3544180334/122723921</a></p><p>百度AI“凉了”以后，国内人工智能谁才是真正的王者？ - 甜草莓的回答 - 知乎 <a href="https://www.zhihu.com/question/334095857/answer/747277456" target="_blank" rel="noreferrer">https://www.zhihu.com/question/334095857/answer/747277456</a></p>',26)])])}const f=e(p,[["render",o]]);export{u as __pageData,f as default};
